package httpserver
import("context";"encoding/json";"net/http";"strings";"time";"github.com/wuangmmo/sodienthoai-platform/apps/api/internal/phone")
type AdminImportHandler struct{Service phone.Service;Token string}
type adminImportInput struct{Source string `json:"source"`;Rows []phone.ImportRow `json:"rows"`}
func(h AdminImportHandler) Import(w http.ResponseWriter,r *http.Request){a:=AdminHandler{Token:h.Token};if !a.authorized(r){writeJSON(w,401,map[string]string{"error":"unauthorized"});return};var in adminImportInput;if json.NewDecoder(http.MaxBytesReader(w,r.Body,2<<20)).Decode(&in)!=nil||len(in.Rows)<1||len(in.Rows)>5000{writeJSON(w,400,map[string]string{"error":"invalid_import"});return};in.Source=strings.TrimSpace(in.Source);if in.Source==""{in.Source="admin-ui"};ctx,cancel:=context.WithTimeout(r.Context(),30*time.Second);defer cancel();accepted,rejected,err:=h.Service.Repository.ImportRows(ctx,in.Source,in.Rows);if err!=nil{writeJSON(w,500,map[string]string{"error":"import_failed"});return};writeJSON(w,200,map[string]any{"accepted":accepted,"rejected":rejected})}
func(h AdminImportHandler) Batches(w http.ResponseWriter,r *http.Request){a:=AdminHandler{Token:h.Token};if !a.authorized(r){writeJSON(w,401,map[string]string{"error":"unauthorized"});return};ctx,cancel:=context.WithTimeout(r.Context(),3*time.Second);defer cancel();rows,err:=h.Service.Repository.DB.QueryContext(ctx,`SELECT id::text,source_name,total_rows,accepted_rows,rejected_rows,status,created_at,completed_at FROM phone_import_batches ORDER BY created_at DESC LIMIT 50`);if err!=nil{writeJSON(w,500,map[string]string{"error":"internal_error"});return};defer rows.Close();items:=[]map[string]any{};for rows.Next(){var id,source,status string;var total,accepted,rejected int64;var created time.Time;var completed *time.Time;if rows.Scan(&id,&source,&total,&accepted,&rejected,&status,&created,&completed)==nil{items=append(items,map[string]any{"id":id,"source":source,"total":total,"accepted":accepted,"rejected":rejected,"status":status,"created_at":created,"completed_at":completed})}};writeJSON(w,200,map[string]any{"data":items})}
